input.command:
cd /tmp/probe/work-suppressions && cat > clean.c <<'EOF'
int foo(int x) {
    return x + 1;
}
int main() {
    return foo(1);
}
EOF
echo "== baseline clean"; /workspace/executable --enable=information clean.c > o 2> e; echo exit=$?; cat o; echo "--STDERR"; cat e
echo "== clean + file suppression"; /workspace/executable --enable=information --suppress=nullPointer:clean.c clean.c 2>&1 >/dev/null
echo "== clean + global suppression"; /workspace/executable --enable=information --suppress=nullPointer clean.c 2>&1 >/dev/null
echo "== clean + line suppression"; /workspace/executable --enable=information --suppress=nullPointer:clean.c:2 clean.c 2>&1 >/dev/null

cd /tmp/probe/work-suppressions && cat > sym.c <<'EOF'
void f(void) {
    int x = 1;
    x = 2;
}
EOF
echo "=== baseline style"; /workspace/executable -q --enable=style sym.c 2>&1
echo "=== xml"; /workspace/executable -q --enable=style --xml sym.c 2>&1

cd /tmp/probe/work-suppressions && cat > i1.c <<'EOF'
int main() {
    int a[3];
    // cppcheck-suppress arrayIndexOutOfBounds
    a[3] = 0;
    return 0;
}
EOF
echo "=== WITHOUT --inline-suppr"; /workspace/executable -q i1.c > o 2> e; echo "exit=$?"; echo OUT:; cat o; echo ERR:; cat e
echo "=== WITHOUT --inline-suppr + --enable=information"; /workspace/executable -q --enable=information i1.c > o 2> e; echo "exit=$?"; echo OUT:; cat o; echo ERR:; cat e
echo "=== WITH --inline-suppr"; /workspace/executable -q --inline-suppr i1.c > o 2> e; echo "exit=$?"; echo OUT:; cat o; echo ERR:; cat e

cd /tmp/probe/work-suppressions && /workspace/executable -q --enable=all i1.c 2>&1 | head -20; echo "-----"; echo "=== inline with unknown id, no --inline-suppr, --enable=all"; cat > i2.c <<'EOF'
